import { styled } from '@hexa-ui/theme';

export const StyledBrandPowerBigNumbers = styled('div', {
  display: 'flex',
  gap: '16px',
  height: '100%',
  width: '100%',

  variants: {
    isYtd: {
      true: {
        '& .brand-power-big-number-ytd.bigNumberCard': {
          height: '100%',
        },
        '& .brand-power-big-number-ytd.bigNumberContainer': {
          height: '100%',
        },
        '& .brand-power-big-number-ytd.bigNumberContainer > div:last-child': {
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flex: 1,
          height: 'auto',
        },
      },
      false: {},
    },
  },
});
